insert into public.nc_mensajes (id, conversacion_id, autor, texto, enviado_at) values
  ('d64ac72c-82a3-4ad2-b7fa-8a6863bbd513', '863cdec3-9919-4cf7-9293-da5a8612aed9', 'cliente', 'Buenas! Te escribo de Titanes Gym en Yerba Buena. Queremos armar un pedido para revender en el gimnasio', now() - interval '190 minutes'),
  ('235b55e7-7e71-4656-bb56-dcf0ac5dd518', '863cdec3-9919-4cf7-9293-da5a8612aed9', 'vendedor', 'Hola Facundo! Qué bueno. Contame qué productos te interesan y te paso precios', now() - interval '172 minutes'),
  ('817c7f94-b0e3-4ffd-8560-f42a486f4b6f', '863cdec3-9919-4cf7-9293-da5a8612aed9', 'cliente', 'Serían 20 potes de whey 2 lb (vainilla y chocolate) y 15 creatinas de 300 g. Tienen precio mayorista?', now() - interval '168 minutes'),
  ('4ac61118-5ae5-4ffd-ab04-5e1395cf0d96', '863cdec3-9919-4cf7-9293-da5a8612aed9', 'cliente', 'Necesitaríamos factura A también', now() - interval '165 minutes'),
  ('4bec8a50-8341-4bea-9512-1a5d35c08fab', '863cdec3-9919-4cf7-9293-da5a8612aed9', 'vendedor', 'Sí, tenemos lista mayorista a partir de 10 unidades. Te la paso en un rato', now() - interval '120 minutes'),
  ('04b39356-fa99-44b0-8c2e-d1150f35d30b', '863cdec3-9919-4cf7-9293-da5a8612aed9', 'cliente', 'Dale, quedo atento. Si no me lo pasan hoy lo compro en otro distribuidor que ya me cotizó', now() - interval '64 minutes'),
  ('6c859b3a-f83e-40a1-9dc2-a8b5ef84a748', '863cdec3-9919-4cf7-9293-da5a8612aed9', 'cliente', 'Hola? Necesito cerrar hoy', now() - interval '52 minutes'),
  ('f33ea017-41e8-48e4-a7df-6b3002f94973', '4465dca5-94a4-4892-91df-aa3ab3ee3881', 'cliente', 'Hola! cuánto sale la creatina monohidrato de 300g?', now() - interval '95 minutes'),
  ('721a8f0d-7d8b-4f0d-aac0-b860530eddad', '4465dca5-94a4-4892-91df-aa3ab3ee3881', 'vendedor', 'Hola Valen! La creatina monohidrato 300 g está $28.900. Si abonás por transferencia tenés 10% off', now() - interval '88 minutes'),
  ('889869f4-cc02-4fcd-a869-b210a5a8b22f', '4465dca5-94a4-4892-91df-aa3ab3ee3881', 'cliente', 'Y el envío a Córdoba capital cuánto sería?', now() - interval '80 minutes'),
  ('14bd5dd4-a5f5-4f65-8e4e-6fd559043ad4', '4465dca5-94a4-4892-91df-aa3ab3ee3881', 'vendedor', 'Por Andreani a domicilio $6.200, llega en 3 a 5 días hábiles. Si superás $60.000 el envío es gratis', now() - interval '74 minutes'),
  ('bb8ae0c4-ef00-4707-a193-73d29f26f094', '4465dca5-94a4-4892-91df-aa3ab3ee3881', 'cliente', 'Ah bueno, y si le sumo un shaker y una whey de 1 kg llego al envío gratis?', now() - interval '18 minutes'),
  ('b5cd9a46-99d2-4706-bd5f-039cb0ede867', 'fa2193d8-aa6c-43fa-a312-32b8f5d893b5', 'cliente', 'Hola, me llegó el pedido #4821 y la whey vino con el sello de seguridad roto', now() - interval '300 minutes'),
  ('08f29a6c-3d25-4a33-977b-f15672c38527', 'fa2193d8-aa6c-43fa-a312-32b8f5d893b5', 'vendedor', 'Hola Rodrigo, lamento lo que pasó. ¿Me mandás una foto del pote?', now() - interval '290 minutes'),
  ('fb59db77-4a1a-401f-9afe-e8acb039319f', 'fa2193d8-aa6c-43fa-a312-32b8f5d893b5', 'cliente', '[Imagen] Ahí está. Es una vergüenza, pagué $54.000 por un producto que no sé si está adulterado', now() - interval '285 minutes'),
  ('57c10f2e-5106-4b42-9d55-9a9dfd688ce5', 'fa2193d8-aa6c-43fa-a312-32b8f5d893b5', 'vendedor', 'Ya lo consulto con el depósito y te aviso', now() - interval '200 minutes'),
  ('d6251112-f991-4f91-ac10-1eebe54a498a', 'fa2193d8-aa6c-43fa-a312-32b8f5d893b5', 'cliente', 'Pasaron 3 horas y nadie me dice nada. Si no me lo cambian hoy hago la denuncia en Defensa del Consumidor y lo publico en Instagram', now() - interval '40 minutes'),
  ('6c14e41a-55b1-4f96-9b0a-cacd53a7e5e3', 'fa2193d8-aa6c-43fa-a312-32b8f5d893b5', 'vendedor', 'Tranqui Rodrigo, ya lo estamos viendo', now() - interval '34 minutes'),
  ('65444f3c-65d5-4c69-a4d8-39e35b16a44c', 'db78c12a-ef1d-44ea-9867-3497961aa791', 'cliente', 'Buenas, qué diferencia hay entre la whey concentrada y la isolate?', now() - interval '1560 minutes'),
  ('4635cc10-1baf-43d2-acc4-044f3cbff8e7', 'db78c12a-ef1d-44ea-9867-3497961aa791', 'vendedor', 'Hola Nico! La isolate tiene más proteína por servicio (27 g vs 22 g) y casi nada de lactosa. Si te cae pesada la leche, te conviene la isolate', now() - interval '1552 minutes'),
  ('579a2fd0-e217-4901-bbbc-c5eb0b00d604', 'db78c12a-ef1d-44ea-9867-3497961aa791', 'cliente', 'Me cae medio mal la lactosa, sí. Cuánto está la isolate 2 lb?', now() - interval '1545 minutes'),
  ('39e1d983-8c57-4400-978b-8d0c60a496ce', 'db78c12a-ef1d-44ea-9867-3497961aa791', 'vendedor', 'La ISO Whey 2 lb está $62.500, con transferencia $56.250. Si confirmás antes de las 17 sale hoy', now() - interval '1540 minutes'),
  ('33c061fb-c457-43fe-b16e-986fe2699cfb', 'db78c12a-ef1d-44ea-9867-3497961aa791', 'cliente', 'Listo, te transfiero. Pasame los datos', now() - interval '1530 minutes'),
  ('63942f1b-0045-4296-845f-e0bcabc9d2f1', 'db78c12a-ef1d-44ea-9867-3497961aa791', 'vendedor', 'Genial! Alias SUPLE.NORT.MP. Mandame el comprobante y tus datos de envío', now() - interval '1527 minutes'),
  ('9a8838c1-07c7-4063-8e03-789375620ed0', 'db78c12a-ef1d-44ea-9867-3497961aa791', 'cliente', 'Enviado el comprobante. Gracias!', now() - interval '1500 minutes'),
  ('0216b169-8a74-4c74-8e9d-608b602730aa', 'db78c12a-ef1d-44ea-9867-3497961aa791', 'vendedor', 'Recibido Nico! Sale hoy por Andreani, a la noche te paso el seguimiento', now() - interval '1496 minutes'),
  ('6db04ac5-641d-4902-b5ec-b8210a13a9a5', '268f684f-493c-4459-a735-abfa42ccce4f', 'cliente', 'Hola, quería consultar por el quemador Thermo Fuel. Tengo hipotiroidismo, lo puedo tomar?', now() - interval '140 minutes'),
  ('988f7136-22ba-4a9a-90c8-7baf8fb473ac', '268f684f-493c-4459-a735-abfa42ccce4f', 'vendedor', 'Hola Carla! Sí, no pasa nada, lo toman muchas chicas. Es re efectivo, en un mes ves resultados', now() - interval '131 minutes'),
  ('75fc1956-ae8a-425f-9044-8c9248849364', '268f684f-493c-4459-a735-abfa42ccce4f', 'cliente', 'Ah buenísimo. Y cuánto sale? tiene mucha cafeína?', now() - interval '125 minutes'),
  ('bc2e44fc-969c-44dd-b14c-eb93cff260cb', '268f684f-493c-4459-a735-abfa42ccce4f', 'vendedor', 'Está $24.500. Tiene 200 mg de cafeína por servicio', now() - interval '118 minutes'),
  ('3bcddbf1-4e4c-44d5-b2f3-f1ea8c59471c', '268f684f-493c-4459-a735-abfa42ccce4f', 'cliente', 'Bueno, lo pienso y te aviso', now() - interval '110 minutes'),
  ('b8dd341e-841d-42b7-8e8f-a15a0409e0a2', '268f684f-493c-4459-a735-abfa42ccce4f', 'vendedor', 'Dale! Cualquier cosa escribime', now() - interval '105 minutes'),
  ('3312e462-76f9-471a-a4cd-ce42840dd882', '69214014-a6fa-4ac0-a0a9-90bf26f35d56', 'cliente', 'Hola! Estoy arrancando en el gym y quiero ganar masa. Qué me recomendás?', now() - interval '2950 minutes'),
  ('14581e0c-b1e1-4f9c-9a9a-308a6ef1ab53', '69214014-a6fa-4ac0-a0a9-90bf26f35d56', 'vendedor', 'Hola Julián! Para arrancar te recomiendo el Combo Volumen: whey 2 lb + creatina 300 g + shaker de regalo. Sale $78.900 (con transferencia $71.000)', now() - interval '2942 minutes'),
  ('21408e10-bd1e-46a4-a82b-2d5fe0ee3fe5', '69214014-a6fa-4ac0-a0a9-90bf26f35d56', 'cliente', 'Y cómo se toma la creatina?', now() - interval '2930 minutes'),
  ('015fbb23-bb6a-4abf-b860-8cc41914033f', '69214014-a6fa-4ac0-a0a9-90bf26f35d56', 'vendedor', '5 g por día, todos los días, con agua o con el batido. No hace falta fase de carga', now() - interval '2925 minutes'),
  ('dcbaadb5-4567-4a08-967a-24c0974ce527', '69214014-a6fa-4ac0-a0a9-90bf26f35d56', 'cliente', 'Buenísimo, lo quiero. Puedo retirar por el local?', now() - interval '2910 minutes'),
  ('43cd9e74-d553-4e26-b222-90e345a1e055', '69214014-a6fa-4ac0-a0a9-90bf26f35d56', 'vendedor', 'Sí! Te lo dejo separado a tu nombre en el local de Tucumán', now() - interval '2905 minutes'),
  ('c4ff59db-28c4-499b-88c2-fd2c9802ca89', '69214014-a6fa-4ac0-a0a9-90bf26f35d56', 'cliente', 'Genial, paso mañana a la tarde', now() - interval '2900 minutes'),
  ('412f4d2b-93cf-403e-be19-54bdd6bcbbcb', '69214014-a6fa-4ac0-a0a9-90bf26f35d56', 'vendedor', 'Julián, ya está listo tu combo para retirar. Te esperamos!', now() - interval '1450 minutes'),
  ('c8084cc3-bc6c-4ca7-ab8c-539e2e02df47', 'fb29d0a3-db3f-4400-9249-26c3f2db7da7', 'cliente', 'Hola, tenés BCAA en polvo? precio?', now() - interval '4400 minutes'),
  ('e3612b61-693e-48da-a0c7-a50958e28db8', 'fb29d0a3-db3f-4400-9249-26c3f2db7da7', 'vendedor', 'Hola Sofi! Sí, BCAA 2:1:1 de 250 g a $21.800', now() - interval '4300 minutes'),
  ('99370c62-cf68-4de4-9d7f-aede3e01be1f', 'fb29d0a3-db3f-4400-9249-26c3f2db7da7', 'cliente', 'Uh, lo vi a $16.000 en otra tienda', now() - interval '4290 minutes'),
  ('43ef903e-ee8a-4781-b91f-d2a5fde572bc', 'fb29d0a3-db3f-4400-9249-26c3f2db7da7', 'vendedor', 'Es otra calidad, el nuestro es importado', now() - interval '4280 minutes'),
  ('f10b0eb8-514e-46ea-95b9-96376c5e6d72', 'fb29d0a3-db3f-4400-9249-26c3f2db7da7', 'cliente', 'Bueno, gracias igual', now() - interval '4270 minutes'),
  ('07d5a8b2-d029-4d45-aa4d-5fb88eed563f', 'a546a707-1a2b-4d37-9deb-fdf1e75723fe', 'cliente', 'Hola buenas tardes, tienen creatina Star Nutrition? Hacen envíos a Concepción?', now() - interval '9 minutes'),
  ('b1f9c2ea-d9f1-4614-980c-20edb1b4ae81', '206e0ab7-04fc-47f6-8613-513017bb0a29', 'cliente', 'Che, cuánto me sale el combo definición?', now() - interval '180 minutes'),
  ('74a43812-2132-49aa-9d7b-68b5e4b41df6', '206e0ab7-04fc-47f6-8613-513017bb0a29', 'vendedor', 'Hola! El Combo Definición (whey isolate 2 lb + quemador + L-carnitina) está $98.500, con transferencia $88.650', now() - interval '170 minutes'),
  ('e40e4c12-c752-4b58-92ed-45fd8f8d7155', '206e0ab7-04fc-47f6-8613-513017bb0a29', 'cliente', 'Me hacés 30% y pago contra entrega? Tengo muchos seguidores, te hago publicidad en mis historias', now() - interval '160 minutes'),
  ('a2dd2405-fbff-41d5-83e5-da514c179698', '206e0ab7-04fc-47f6-8613-513017bb0a29', 'vendedor', 'Dejame ver qué puedo hacer', now() - interval '150 minutes'),
  ('6d6d67da-1ff8-455a-97f9-bc9db1e1a2b9', '206e0ab7-04fc-47f6-8613-513017bb0a29', 'cliente', 'Tengo 12k seguidores, les va a servir', now() - interval '120 minutes'),
  ('0a15a9cc-f6cc-4bb8-81b9-2fa5b86c8b6b', '206e0ab7-04fc-47f6-8613-513017bb0a29', 'cliente', 'Y? me confirmás o no?', now() - interval '71 minutes'),
  ('d31238a3-07fc-4377-bf76-d1e295dc554f', '65fae466-1e3a-4c44-b2e0-943169ef1fb1', 'cliente', 'Hola! Compré el jueves, me pasás el seguimiento del envío a Salta?', now() - interval '600 minutes'),
  ('76084b76-9d02-45b9-86a4-fbbbf378f486', '65fae466-1e3a-4c44-b2e0-943169ef1fb1', 'vendedor', 'Hola Lorena! Sí, el código es AND-3307-9921. Está en sucursal Salta, mañana sale a distribución', now() - interval '592 minutes'),
  ('db24b5e3-b99f-413c-a2c7-b1b9a1b6e0ad', '65fae466-1e3a-4c44-b2e0-943169ef1fb1', 'cliente', 'Genial, gracias!', now() - interval '585 minutes'),
  ('b3430435-2186-4246-be45-c76f31be2a14', '65fae466-1e3a-4c44-b2e0-943169ef1fb1', 'vendedor', 'De nada! Cuando te llegue contanos qué tal la whey. En tu próxima compra tenés 10% off', now() - interval '580 minutes'),
  ('3ba8dfc8-3df7-4876-8bf5-130f8afcd8f1', 'e7d0e8d6-f5a4-4dd6-a868-6e67bf6f0ac5', 'cliente', 'Buenas, me pasás precio del combo definición y si tienen sabor frutilla', now() - interval '3100 minutes'),
  ('80ae4058-ec99-4ae6-b56a-a9f05fa85455', 'e7d0e8d6-f5a4-4dd6-a868-6e67bf6f0ac5', 'vendedor', 'Hola Federico. Combo Definición $98.500. Frutilla no hay, solo vainilla y chocolate', now() - interval '3060 minutes'),
  ('2f68728b-b3ff-451b-a217-2a640ba455b2', 'e7d0e8d6-f5a4-4dd6-a868-6e67bf6f0ac5', 'cliente', 'Ok, lo pienso', now() - interval '3050 minutes'),
  ('dca3f433-f73e-49f4-b995-9113ae3c4ab1', 'e7d0e8d6-f5a4-4dd6-a868-6e67bf6f0ac5', 'vendedor', 'Ok', now() - interval '3045 minutes'),
  ('33e710c5-18ec-4c8e-b86d-ee7a849e236e', '2d1f9eee-cb1f-4658-99e0-b6c10b475f79', 'cliente', 'Hola! Qué pre entreno tienen que no tenga tanta cafeína?', now() - interval '48 minutes'),
  ('d023fdb5-d386-4d0c-ab7f-b2710af8082a', '2d1f9eee-cb1f-4658-99e0-b6c10b475f79', 'vendedor', 'Hola Andrés! Tenemos el Pump Zero, sin estimulantes: citrulina, beta alanina y arginina. $26.700', now() - interval '44 minutes'),
  ('aae4546c-2601-4ecf-8487-f26da20dc5fb', '2d1f9eee-cb1f-4658-99e0-b6c10b475f79', 'cliente', 'Y se puede combinar con creatina?', now() - interval '40 minutes'),
  ('6bd3396e-fe0d-4c62-9e37-d48502fe6376', '2d1f9eee-cb1f-4658-99e0-b6c10b475f79', 'vendedor', 'Sí, sin problema, muchos lo toman juntos. Si llevás los dos te hago $49.900 con transferencia', now() - interval '37 minutes'),
  ('b5b22afb-bb07-4ab8-a023-6a0d06621c74', '2d1f9eee-cb1f-4658-99e0-b6c10b475f79', 'cliente', 'Mmm dale, mañana te confirmo cuando cobre', now() - interval '30 minutes'),
  ('201a4e8a-0204-498c-925c-80b237c4b0ba', '2d1f9eee-cb1f-4658-99e0-b6c10b475f79', 'vendedor', 'Perfecto Andrés, te lo reservo hasta mañana a la noche', now() - interval '28 minutes'),
  ('0948f222-b9c3-49f1-8443-8972a10ae611', '1e07b074-c5df-4d9a-b754-46bc1a9c46af', 'cliente', 'Hola, soy Pablo de Fuerza Norte. Necesito reponer: 12 whey 2 lb y 10 creatinas. Lista mayorista como siempre', now() - interval '1400 minutes'),
  ('a8d30ffd-c32c-4856-bbfc-86c29314fa67', '1e07b074-c5df-4d9a-b754-46bc1a9c46af', 'vendedor', 'Hola Pablo! Whey 2 lb $41.200 c/u y creatina 300 g $19.900 c/u. Total $693.400 con factura A. Envío sin cargo a Tafí', now() - interval '1392 minutes'),
  ('f134a030-dc9d-45b4-bfd9-ba89bf86bff2', '1e07b074-c5df-4d9a-b754-46bc1a9c46af', 'cliente', 'Perfecto. Te transfiero hoy', now() - interval '1380 minutes'),
  ('fcc12180-c2c8-43bd-9ad6-89adc018650f', '1e07b074-c5df-4d9a-b754-46bc1a9c46af', 'vendedor', 'Gracias! Lo despachamos mañana a primera hora', now() - interval '1376 minutes'),
  ('6f3b833c-88e6-4ee9-8046-ad62a64a51a1', '1e07b074-c5df-4d9a-b754-46bc1a9c46af', 'cliente', 'Transferido, te mando comprobante', now() - interval '1300 minutes'),
  ('c139a08b-0c51-431e-b305-2d5795d71adb', '1e07b074-c5df-4d9a-b754-46bc1a9c46af', 'vendedor', 'Recibido. Mañana 9 h sale el pedido', now() - interval '1290 minutes'),
  ('39ad213b-844a-4b89-955d-ea7efecb3948', '7f66abf1-19de-494d-98ae-167500ce4361', 'cliente', 'Hola! Soy nutricionista deportiva en San Miguel. Tienen algún convenio o descuento para derivar pacientes?', now() - interval '27 minutes');
