insert into public.nc_analisis (id, conversacion_id, resumen, intencion, productos, objeciones, proximo_paso, puntajes, motivo, solicitado_por, creado_at) values
  ('03c2b7cc-e6a2-4ff5-806d-801566444141', '863cdec3-9919-4cf7-9293-da5a8612aed9', 'Gimnasio de Yerba Buena pide cotización mayorista (20 whey + 15 creatinas) con factura A. El vendedor prometió la lista pero no la envió; el cliente amenaza con comprar a otro distribuidor.', 'Compra mayorista para reventa', array['Whey Protein 2 lb', 'Creatina monohidrato 300 g'], array['Urgencia: necesita cerrar hoy', 'Tiene una cotización de la competencia'], 'Enviar ya la lista mayorista para 35 unidades con factura A y ofrecer envío sin cargo a Yerba Buena.', '{"respuesta":{"puntaje":3,"comentario":"Más de 45 min sin responder a un pedido mayorista."},"atencion":{"puntaje":7,"comentario":"Trato cordial y claro."},"tecnica":{"puntaje":4,"comentario":"No cotizó ni intentó el cierre pese a la intención explícita."},"seguimiento":{"puntaje":2,"comentario":"Prometió la lista \"en un rato\" y no la envió."}}'::jsonb, 'mensajes', null, now() - interval '30 minutes'),
  ('9bda3717-17c2-4b00-8b51-0315ed11f297', '4465dca5-94a4-4892-91df-aa3ab3ee3881', 'Clienta de Córdoba consulta creatina y envío. Ahora pregunta si sumando whey 1 kg y shaker llega al envío gratis.', 'Compra minorista con envío', array['Creatina monohidrato 300 g', 'Whey Protein 1 kg', 'Shaker'], array['Costo de envío'], 'Confirmar el total con envío gratis y enviar el link de pago.', '{"respuesta":{"puntaje":8,"comentario":"Respuestas en menos de 10 min."},"atencion":{"puntaje":9,"comentario":"Claro y cercano; informa el descuento por transferencia."},"tecnica":{"puntaje":8,"comentario":"Usó el umbral de envío gratis para subir el ticket."},"seguimiento":{"puntaje":6,"comentario":"Mensaje nuevo sin respuesta hace 18 min."}}'::jsonb, 'tiempo', null, now() - interval '15 minutes'),
  ('1862025c-8a8f-4485-a40b-5b3e40bb56f2', 'fa2193d8-aa6c-43fa-a312-32b8f5d893b5', 'Reclamo por whey con sello de seguridad roto (pedido #4821). El cliente espera hace horas y amenaza con denuncia y exposición pública.', 'Reclamo / cambio de producto', array['Whey Protein 2 lb'], array['Desconfianza sobre la calidad del producto'], 'Supervisor: ofrecer cambio inmediato con envío sin cargo y disculpa formal. Evitar respuestas informales.', '{"respuesta":{"puntaje":3,"comentario":"Pasaron casi 3 h sin novedades."},"atencion":{"puntaje":4,"comentario":"\"Tranqui\" minimiza el reclamo de un cliente enojado."},"tecnica":{"puntaje":5,"comentario":"Pidió evidencia correctamente, pero no ofreció solución."},"seguimiento":{"puntaje":3,"comentario":"No informó avances del caso."}}'::jsonb, 'mensajes', null, now() - interval '30 minutes'),
  ('e6f4f991-cc71-49e7-b089-a982bbf91bee', 'db78c12a-ef1d-44ea-9867-3497961aa791', 'Cliente con intolerancia a la lactosa. El vendedor explicó la diferencia entre concentrada e isolate y cerró la venta de ISO Whey 2 lb por transferencia.', 'Compra minorista', array['ISO Whey 2 lb'], array['Intolerancia a la lactosa'], 'Enviar código de seguimiento y ofrecer recompra en 30 días.', '{"respuesta":{"puntaje":9,"comentario":"Respuestas en minutos."},"atencion":{"puntaje":9,"comentario":"Explicación técnica clara y simple."},"tecnica":{"puntaje":10,"comentario":"Detectó la necesidad y generó urgencia con el despacho del día."},"seguimiento":{"puntaje":9,"comentario":"Confirmó el comprobante y anticipó el seguimiento."}}'::jsonb, 'mensajes', null, now() - interval '1490 minutes'),
  ('20dfe844-c8d4-4c09-b637-f0615e64c9b9', '268f684f-493c-4459-a735-abfa42ccce4f', 'Consulta por quemador Thermo Fuel de una clienta con hipotiroidismo. El vendedor afirmó que puede tomarlo sin consultar al médico y prometió resultados.', 'Pérdida de peso', array['Quemador Thermo Fuel'], array['Duda por condición de salud', 'Indecisión ("lo pienso")'], 'Recomendar consulta médica antes de usar termogénicos y ofrecer alternativas sin estimulantes.', '{"respuesta":{"puntaje":8,"comentario":"Respondió rápido."},"atencion":{"puntaje":6,"comentario":"Cordial, pero minimizó una consulta de salud."},"tecnica":{"puntaje":4,"comentario":"Promesa de resultados y sin alternativas."},"seguimiento":{"puntaje":5,"comentario":"No retomó tras el \"lo pienso\"."}}'::jsonb, 'tiempo', null, now() - interval '100 minutes'),
  ('2fc2e34d-a674-4fe1-a1e1-95a4b90e349b', '69214014-a6fa-4ac0-a0a9-90bf26f35d56', 'Principiante que busca ganar masa. El vendedor recomendó el Combo Volumen, explicó la toma de creatina y cerró con retiro en el local.', 'Compra minorista', array['Combo Volumen', 'Whey Protein 2 lb', 'Creatina monohidrato 300 g', 'Shaker'], '{}'::text[], 'Postventa: consultar en 2 semanas cómo le va con el combo.', '{"respuesta":{"puntaje":9,"comentario":"Respuestas en menos de 10 min."},"atencion":{"puntaje":9,"comentario":"Tono cercano y didáctico."},"tecnica":{"puntaje":9,"comentario":"Recomendó un combo acorde al objetivo."},"seguimiento":{"puntaje":10,"comentario":"Avisó que el pedido estaba listo para retirar."}}'::jsonb, 'mensajes', null, now() - interval '1440 minutes'),
  ('f2f51669-deb2-4794-a8c4-2dfbdbaed4e8', 'fb29d0a3-db3f-4400-9249-26c3f2db7da7', 'Consulta por BCAA. La clienta encontró un precio menor en otra tienda y el vendedor no defendió el valor del producto. Venta perdida.', 'Compra minorista', array['BCAA 2:1:1 250 g'], array['Precio más bajo en la competencia'], 'Retomar con una alternativa de menor precio o un combo con aminoácidos.', '{"respuesta":{"puntaje":3,"comentario":"Primera respuesta a la 1 h 40 min."},"atencion":{"puntaje":6,"comentario":"Correcto pero seco."},"tecnica":{"puntaje":3,"comentario":"No argumentó valor ni ofreció alternativa ante la objeción de precio."},"seguimiento":{"puntaje":2,"comentario":"Sin seguimiento."}}'::jsonb, 'mensajes', null, now() - interval '4260 minutes'),
  ('3ae31e74-4561-41e1-b0a7-02b49f5c05cb', '206e0ab7-04fc-47f6-8613-513017bb0a29', 'Cliente pide 30% de descuento y pago contra entrega a cambio de publicidad en redes. El vendedor quedó en "ver qué puede hacer" y no volvió a responder.', 'Compra con descuento especial', array['Combo Definición', 'Whey Isolate 2 lb', 'Quemador', 'L-Carnitina'], array['Pide 30% de descuento', 'Pago contra entrega'], 'Responder con la política vigente: hasta 10% por transferencia, sin contra entrega. Un canje de difusión requiere aprobación del supervisor.', '{"respuesta":{"puntaje":5,"comentario":"Demoras crecientes; último mensaje sin respuesta hace más de 1 h."},"atencion":{"puntaje":7,"comentario":"Correcto."},"tecnica":{"puntaje":5,"comentario":"\"Dejame ver\" sin una respuesta concreta."},"seguimiento":{"puntaje":3,"comentario":"Dejó al cliente sin respuesta."}}'::jsonb, 'tiempo', null, now() - interval '60 minutes'),
  ('2ad0c615-ad1b-417b-812f-2c5894ce0c0f', '65fae466-1e3a-4c44-b2e0-943169ef1fb1', 'Clienta de Salta pide seguimiento del envío. El vendedor respondió rápido con el código y ofreció descuento para la próxima compra.', 'Seguimiento de envío', array['Whey Protein 2 lb'], '{}'::text[], 'Confirmar la entrega mañana y pedir reseña.', '{"respuesta":{"puntaje":9,"comentario":"Respuesta en 8 min."},"atencion":{"puntaje":9,"comentario":"Amable y concreto."},"tecnica":{"puntaje":8,"comentario":"Incentivó la recompra con descuento."},"seguimiento":{"puntaje":9,"comentario":"Buen cierre de postventa."}}'::jsonb, 'mensajes', null, now() - interval '575 minutes'),
  ('2bb6f437-ffbd-403d-8b4c-38fcad56c17e', 'e7d0e8d6-f5a4-4dd6-a868-6e67bf6f0ac5', 'Consulta por Combo Definición sabor frutilla. Sin stock del sabor; el vendedor no ofreció alternativa y no retomó la conversación en 2 días.', 'Compra minorista', array['Combo Definición'], array['Sabor no disponible'], 'Retomar hoy ofreciendo sabores alternativos o whey sin sabor + saborizante.', '{"respuesta":{"puntaje":6,"comentario":"Primera respuesta a los 40 min."},"atencion":{"puntaje":6,"comentario":"Respuestas escuetas (\"Ok\")."},"tecnica":{"puntaje":4,"comentario":"No ofreció alternativa de sabor ni intentó el cierre."},"seguimiento":{"puntaje":2,"comentario":"Sin seguimiento en 2 días."}}'::jsonb, 'tiempo', null, now() - interval '3000 minutes'),
  ('a0454678-89b0-410c-91cf-1d057c3e5bfe', '2d1f9eee-cb1f-4658-99e0-b6c10b475f79', 'Cliente busca pre entreno sin estimulantes. El vendedor recomendó Pump Zero, armó combo con creatina y lo reservó hasta mañana.', 'Compra minorista', array['Pre entreno Pump Zero', 'Creatina monohidrato 300 g'], array['Espera a cobrar'], 'Recordar la reserva mañana a las 19 h con el link de pago.', '{"respuesta":{"puntaje":9,"comentario":"Respuestas en 2 a 4 min."},"atencion":{"puntaje":9,"comentario":"Claro y empático."},"tecnica":{"puntaje":9,"comentario":"Armó combo y reservó con fecha."},"seguimiento":{"puntaje":8,"comentario":"Dejó el seguimiento pactado."}}'::jsonb, 'mensajes', null, now() - interval '25 minutes'),
  ('4763108b-0c80-4128-812a-1e0e6a72a850', '1e07b074-c5df-4d9a-b754-46bc1a9c46af', 'Gimnasio cliente habitual repone stock mayorista: 12 whey + 10 creatinas por $693.400 con factura A. Pago confirmado.', 'Compra mayorista recurrente', array['Whey Protein 2 lb', 'Creatina monohidrato 300 g'], '{}'::text[], 'Confirmar despacho y agendar la próxima reposición en 30 días.', '{"respuesta":{"puntaje":9,"comentario":"Respuesta en 8 min."},"atencion":{"puntaje":9,"comentario":"Profesional y preciso."},"tecnica":{"puntaje":9,"comentario":"Cotización completa en un solo mensaje."},"seguimiento":{"puntaje":9,"comentario":"Confirmó pago y despacho."}}'::jsonb, 'mensajes', null, now() - interval '1285 minutes');
insert into public.nc_alertas (id, conversacion_id, tipo, situacion_id, nivel, titulo, motivo, fragmento, estado, creada_at, atendida_por, atendida_at, comentario) values
  ('5ebfada9-223a-4868-96ea-c035e8ffd19b', '863cdec3-9919-4cf7-9293-da5a8612aed9', 'intervencion', 'mayorista', 'critico', 'Venta mayorista en riesgo', 'Pedido de 35 unidades con factura A (≈ $1.100.000). El vendedor prometió la lista mayorista y no la envió; el cliente menciona una cotización de la competencia y necesita cerrar hoy.', 'Si no me lo pasan hoy lo compro en otro distribuidor que ya me cotizó', 'abierta', now() - interval '30 minutes', null, null, null),
  ('4265b2c9-3348-4ed4-a447-dc95dc585379', '863cdec3-9919-4cf7-9293-da5a8612aed9', 'espera', null, 'critico', 'Cliente esperando respuesta', null, null, 'abierta', now() - interval '7 minutes', null, null, null),
  ('1df8aec4-25ad-4391-b583-498220fe654c', 'fa2193d8-aa6c-43fa-a312-32b8f5d893b5', 'intervencion', 'reclamo', 'critico', 'Cliente enojado / reclamo', 'Reclamo por producto con sello roto sin resolución en 3 h. El cliente amenaza con denuncia en Defensa del Consumidor y exposición en Instagram. La última respuesta del vendedor es informal.', 'Si no me lo cambian hoy hago la denuncia en Defensa del Consumidor y lo publico en Instagram', 'abierta', now() - interval '32 minutes', null, null, null),
  ('76ce421f-c8c5-4539-b6fa-6c78f5b009e3', '268f684f-493c-4459-a735-abfa42ccce4f', 'intervencion', 'error', 'advertencia', 'Error del vendedor', 'El vendedor indicó que un termogénico con 200 mg de cafeína es apto para una clienta con hipotiroidismo sin sugerir consulta médica, y prometió resultados.', 'Sí, no pasa nada, lo toman muchas chicas. Es re efectivo, en un mes ves resultados', 'abierta', now() - interval '100 minutes', null, null, null),
  ('f0f59a6e-f34a-4def-90ca-dd215df46934', '206e0ab7-04fc-47f6-8613-513017bb0a29', 'intervencion', 'politica', 'advertencia', 'Pedido fuera de política', 'El cliente pide 30% de descuento y pago contra entrega. La política vigente permite hasta 10% por transferencia y no ofrece contra entrega.', 'Me hacés 30% y pago contra entrega?', 'abierta', now() - interval '60 minutes', null, null, null),
  ('76777385-abe8-4aeb-a465-6d79f624ce62', '206e0ab7-04fc-47f6-8613-513017bb0a29', 'espera', null, 'critico', 'Cliente esperando respuesta', null, null, 'abierta', now() - interval '26 minutes', null, null, null),
  ('82984a96-c0b5-406c-b579-d74b0ce8f387', '4465dca5-94a4-4892-91df-aa3ab3ee3881', 'espera', null, 'advertencia', 'Cliente esperando respuesta', null, null, 'abierta', now() - interval '3 minutes', null, null, null),
  ('1e41b162-90b7-42c3-945e-298b3c82772e', '7f66abf1-19de-494d-98ae-167500ce4361', 'espera', null, 'advertencia', 'Cliente esperando respuesta', null, null, 'abierta', now() - interval '12 minutes', null, null, null),
  ('cc2c0292-a63d-4719-b977-e493a235a9d2', 'fb29d0a3-db3f-4400-9249-26c3f2db7da7', 'intervencion', 'competencia', 'advertencia', 'Venta perdida por precio', 'La clienta comparó con un precio de la competencia y el vendedor no ofreció alternativas.', 'Uh, lo vi a $16.000 en otra tienda', 'atendida', now() - interval '4260 minutes', 'af3c009e-f121-4a29-b89c-8147ebe03b59', now() - interval '4000 minutes', 'Lo charlé con Lucas: ofrecer BCAA nacional como alternativa.'),
  ('e9521966-bea0-4b4a-ac78-e9e084711415', 'e7d0e8d6-f5a4-4dd6-a868-6e67bf6f0ac5', 'intervencion', 'seguimiento', 'advertencia', 'Cotización sin seguimiento', 'Cotización enviada hace más de 24 h sin seguimiento del vendedor.', 'Ok, lo pienso', 'atendida', now() - interval '1600 minutes', 'af3c009e-f121-4a29-b89c-8147ebe03b59', now() - interval '1500 minutes', 'Le pedí a Lucas que retome hoy.');
